    printf("%u", x->v[x->n - 1]);
    while (i-- > 1) printf("%09u", x->v[i - 1]);
    putchar(10);
}

static unsigned long long fib_double(unsigned long long n, Big *out)
{
    Big a, b, c, d, e, t;
    int top, i;

    big_init(&a);
    big_init(&b);
    big_init(&c);
    big_init(&d);
    big_init(&e);
    big_init(&t);

    big_set_u64(&a, 0);
    big_set_u64(&b, 1);

    if (n > 0) {
        top = 63;
        while (((n >> top) & 1ULL) == 0) top--;
        for (i = top; i >= 0; i--) {
            big_add(&t, &b, &b);     /* t = 2b        */
            big_sub(&t, &t, &a);     /* t = 2b - a    */
            big_mul(&c, &a, &t);     /* c = a*(2b-a)  */
            big_mul(&e, &a, &a);     /* e = a*a       */
            big_mul(&d, &b, &b);     /* d = b*b       */
            big_add(&d, &e, &d);     /* d = a*a + b*b */
