                big_copy(&b, &e);
            } else {
                big_copy(&a, &c);
                big_copy(&b, &d);
            }
        }
    }

    big_copy(out, &a);
    big_free(&a);
    big_free(&b);
    big_free(&c);
    big_free(&d);
    big_free(&e);
    big_free(&t);
    return 0;
}

int main(int argc, char **argv)
{
    unsigned long long n;
    char *end = NULL;
    Big result;

    if (argc < 2) {
        fputs("usage: main N\n", stderr);
        return 1;
    }
    if (argv[1][0] == 45) {           /* leading minus sign */
        fputs("N must be a non-negative integer\n", stderr);
        return 1;
    }
    n = strtoull(argv[1], &end, 10);
